INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'Úvod do Rustu', '<h2>Proč Rust?</h2><p>Rust je systémový jazyk zaměřený na bezpečnost paměti, rychlost a souběžnost. Nemá garbage collector — místo toho používá ownership systém, který kompilátor ověřuje při překladu. Rust opakovaně volí nejoblíbenější jazyk v Stack Overflow průzkumech.</p><h2>Instalace — rustup</h2><p><code>rustup</code> je oficiální instalační a verzovací nástroj. Nainstaluje kompilátor <code>rustc</code>, balíčkovací systém <code>cargo</code> a dokumentaci.</p><pre><code># Instalace (Linux/macOS)\ncurl --proto ''=https'' --tlsv1.2 -sSf https://sh.rustup.rs | sh\n\n# Instalace (Windows)\n# Stáhni rustup-init.exe z https://rustup.rs\n\n# Ověření\nrustc --version   # např. rustc 1.82.0\ncargo --version   # např. cargo 1.82.0\nrustup update     # aktualizace na nejnovější stable</code></pre><h2>Cargo</h2><p><code>cargo</code> je build systém a správce balíčků v jednom. Vytvoří projekt, zkompiluje, spustí testy, stáhne závislosti z crates.io.</p><pre><code>cargo new ahoj_svetlo      # vytvoří nový projekt\ncd ahoj_svetlo\ncargo build                 # zkompiluje (debug)\ncargo run                   # zkompiluje a spustí\ncargo build --release       # optimalizovaná verze\ncargo check                 # rychlá kontrola bez překladu</code></pre><h2>Hello World</h2><p>Každý Rust program začíná funkcí <code>main</code>. Makro <code>println!</code> vypíše na stdout. Pozor na vykřičník — je to makro, ne funkce.</p><pre><code>fn main() {\n    println!("Ahoj, VeVit!");\n    let jmeno = "Rust";\n    let verze = 1.82;\n    println!("{} verze {}", jmeno, verze);\n}</code></pre><p>Cargo.toml je konfigurační soubor projektu — obsahuje název, verzi, závislosti (crates). Zdrojový kód je ve <code>src/main.rs</code>.</p>', 'lesson', 1, 15, 15),

(@kurs_id, 'Ownership a Borrowing', '<h2>Ownership — tři pravidla</h2><p>1. Každá hodnota má jednoho vlastníka (owner).<br/>2. V jednu chvíli existuje právě jeden owner.<br/>3. Když owner opustí scope, hodnota je zrušena (drop).</p><pre><code>fn main() {\n    let s1 = String::from("ahoj");\n    let s2 = s1;         // s1 přesunuto (move) — s1 nelze dál použít\n    println!("{}", s2);  // OK\n    // println!("{}", s1); // CHYBA: value borrowed after move\n}</code></pre><h2>Klonování</h2><p>Pokud potřebuješ kopii, použij <code>clone()</code>. Hluboká kopie alokuje novou paměť.</p><pre><code>let s1 = String::from("ahoj");\nlet s2 = s1.clone();  // hluboká kopie\nprintln!("{} {}", s1, s2);  // obě platné</code></pre><h2>Borrowing — reference</h2><p><code>&amp;T</code> je neměnná reference (immutable borrow). <code>&amp;mut T</code> je měnná reference (mutable borrow). Pravidla:</p><p>— Libovolný počet &amp;T současně.<br/>— NEBO právě jedna &amp;mut T.<br/>— Referencí musí vždy platit, že odkazovaná hodnota žije dostatečně dlouho.</p><pre><code>fn delka(s: &amp;String) -> usize {\n    s.len()\n}\n\nfn main() {\n    let s = String::from("ahoj");\n    let len = delka(&amp;s);  // borrow — s stále vlastníme\n    println!("Délka {} = {}", s, len);\n}</code></pre><h2>Borrow checker</h2><p>Kompilátor Rustu obsahuje borrow checker — staticky ověřuje pravidla referencí. Pokud kód porušuje pravidla, nepřeloží se. Tím Rust garantuje bezpečnost paměti za běhu bez GC.</p><pre><code>fn main() {\n    let mut s = String::from("ahoj");\n    let r1 = &amp;mut s;\n    // let r2 = &amp;mut s; // CHYBA: druhá mutable borrow\n    r1.push_str(" svete");\n    println!("{}", r1);\n}</code></pre>', 'lesson', 2, 15, 18),

(@kurs_id, 'Structs a enums', '<h2>Struct</h2><p>Struktura seskupuje data. Tři varianty: pojmenovaná (named), tuple-like, unit-like. K instanci přistupuješ tečkovou notací.</p><pre><code>struct Uzivatel {\n    jmeno: String,\n    vek: u32,\n    aktivni: bool,\n}\n\nfn main() {\n    let karel = Uzivatel {\n        jmeno: String::from("Karel"),\n        vek: 25,\n        aktivni: true,\n    };\n    println!("{} je {}", karel.jmeno, karel.vek);\n}</code></pre><h2>Derive makra</h2><p><code>#[derive(Debug, Clone, PartialEq)]</code> automaticky implementuje běžné traity. <code>Debug</code> umožní <code>println!("{:?}", x)</code>.</p><pre><code>#[derive(Debug, Clone)]\nstruct Bod {\n    x: f64,\n    y: f64,\n}\n\nfn main() {\n    let a = Bod { x: 1.0, y: 2.0 };\n    let b = a.clone();\n    println!("{:?}", a);  // Bod { x: 1.0, y: 2.0 }\n}</code></pre><h2>impl bloky</h2><p>Metody se definují v <code>impl</code> blocích. První parametr <code>&amp;self</code> = metoda instance. <code>Self</code> je alias pro typ. Asociované funkce (bez self) slouží jako konstruktory.</p><pre><code>impl Bod {\n    fn new(x: f64, y: f64) -> Self {\n        Self { x, y }\n    }\n    fn vzdalenost(&amp;self, other: &amp;Bod) -> f64 {\n        ((self.x - other.x).powi(2) + (self.y - other.y).powi(2)).sqrt()\n    }\n}</code></pre><h2>Enum</h2><p>Enum může nést data v každé variantě. Kombinuje výhody sum typů a tagged unions.</p><pre><code>enum Tvar {\n    Kruh(f64),\n    Ctverec(f64),\n    Obdelnik { sirka: f64, vyska: f64 },\n}\n\nfn obsah(tvar: &amp;Tvar) -> f64 {\n    match tvar {\n        Tvar::Kruh(r) => std::f64::consts::PI * r * r,\n        Tvar::Ctverec(a) => a * a,\n        Tvar::Obdelnik { sirka, vyska } => sirka * vyska,\n    }\n}</code></pre>', 'lesson', 3, 15, 18),

(@kurs_id, 'Result<T,E> a Option<T>', '<h2>Option&lt;T&gt;</h2><p>Hodnota, která může nebo nemusí existovat. <code>Some(T)</code> = hodnota přítomna, <code>None</code> = chybí. Nahrazuje null — Rust nemá null reference.</p><pre><code>fn najdi_uzivatele(id: u32) -> Option&lt;String&gt; {\n    if id == 1 {\n        Some(String::from("Karel"))\n    } else {\n        None\n    }\n}\n\nfn main() {\n    match najdi_uzivatele(1) {\n        Some(jmeno) => println!("Nalezen: {}", jmeno),\n        None => println!("Nenalezen"),\n    }\n}</code></pre><h2>Result&lt;T, E&gt;</h2><p>Výsledek operace, která může selhat. <code>Ok(T)</code> = úspěch, <code>Err(E)</code> = chyba. Funkce vrací Result místo vyhazování výjimky.</p><pre><code>use std::fs;\n\nfn cti_soubor(cesta: &amp;str) -> Result&lt;String, std::io::Error&gt; {\n    fs::read_to_string(cesta)\n}\n\nfn main() {\n    match cti_soubor("data.txt") {\n        Ok(obsah) => println!("{}", obsah),\n        Err(e) => eprintln!("Chyba: {}", e),\n    }\n}</code></pre><h2>? operátor</h2><p>Operátor <code>?</code> zkracuje zpracování Result/Option. Pokud je výsledek Err/None, předčasně vrátí chybu z funkce. Pokud Ok/Some, rozbalí hodnotu.</p><pre><code>fn cti_a_zpracuj(cesta: &amp;str) -> Result&lt;u32, std::io::Error&gt; {\n    let obsah = fs::read_to_string(cesta)?;\n    let cislo: u32 = obsah.trim().parse().map_err(|e| {\n        std::io::Error::new(std::io::ErrorKind::InvalidData, e)\n    })?;\n    Ok(cislo * 2)\n}</code></pre><h2>Kombinátory</h2><p><code>map</code>, <code>and_then</code>, <code>unwrap_or</code>, <code>unwrap_or_default</code> — řetězí transformace bez match.</p><pre><code>let x: Option&lt;i32&gt; = Some(5);\nlet y = x.map(|v| v * 2).unwrap_or(0);  // 10\n\nlet res: Result&lt;i32, &amp;str&gt; = Ok(10);\nlet z = res.and_then(|v| Ok(v + 1)).unwrap_or(0);  // 11</code></pre>', 'lesson', 4, 15, 18),

(@kurs_id, 'Traits', '<h2>Definice traitu</h2><p>Trait definuje sdílené chování — podobně jako interface v jiných jazycích. Deklaruje signatury metod, které typy musí implementovat.</p><pre><code>trait Popis {\n    fn popis(&amp;self) -> String;\n    fn shrnuti(&amp;self) -> String {\n        format!("Zkracene: {}", self.popis())  // výchozí implementace\n    }\n}</code></pre><h2>Implementace traitu</h2><p><code>impl Trait for Type</code> přiřadí trait konkrétnímu typu. Typ musí implementovat všechny metody bez výchozího těla.</p><pre><code>struct Kniha {\n    nazev: String,\n    autor: String,\n}\n\nimpl Popis for Kniha {\n    fn popis(&amp;self) -> String {\n        format!("{} od {}", self.nazev, self.autor)\n    }\n}\n\nfn main() {\n    let k = Kniha { nazev: "Rust v praxi".into(), autor: "Novak".into() };\n    println!("{}", k.popis());\n    println!("{}", k.shrnuti());  // výchozí implementace\n}</code></pre><h2>Trait objects — dyn</h2><p><code>dyn Trait</code> umožňuje dynamický dispatch. Hodnoty různých typů se sjednotí přes společný trait. Vyžaduje <code>&amp;</code> nebo <code>Box</code>.</p><pre><code>fn vypis(vec: &amp;Vec&lt;Box&lt;dyn Popis&gt;&gt;) {\n    for item in vec {\n        println!("{}", item.popis());\n    }\n}\n\nfn main() {\n    let vec: Vec&lt;Box&lt;dyn Popis&gt;&gt; = vec![\n        Box::new(Kniha { nazev: "A".into(), autor: "X".into() }),\n    ];\n    vypis(&amp;vec);\n}</code></pre><h2>Trait bounds</h2><p>Omezí generický parametr na typy, které implementují daný trait. Zápis <code>T: Trait</code> nebo <code>where T: Trait</code>.</p><pre><code>fn nejvetsi&lt;T: PartialOrd + Copy&gt;(seznam: &amp;[T]) -> T {\n    let mut max = seznam[0];\n    for &amp;item in seznam {\n        if item > max { max = item; }\n    }\n    max\n}\n\n// where klauzule (čitelnější pro více bounds)\nfn zpracuj&lt;T&gt;(data: T) -> String\nwhere\n    T: Popis + Clone,\n{\n    data.popis()\n}</code></pre>', 'lesson', 5, 15, 20),

(@kurs_id, 'Lifetimes', '<h2>Proč lifetimes?</h2><p>Lifetime anotace pomáhají borrow checkeru ověřit, že reference žijí dostatečně dlouho. Neovlivňují běh programu — čistě compile-time informace.</p><h2>Anotace</h2><p>Označují se apostrofem: <code>''a</code>, <code>''b</code>. Propojují vstupní a výstupní reference — kompilátor ví, že výstup žije maximálně tak dlouho jako vstup.</p><pre><code>fn delsi&lt;''a&gt;(x: &amp;''a str, y: &amp;''a str) -> &amp;''a str {\n    if x.len() > y.len() { x } else { y }\n}\n\nfn main() {\n    let a = String::from("ahoj");\n    let vysledek;\n    {\n        let b = String::from("svete");\n        vysledek = delsi(&amp;a, &amp;b); // chyba: b nežije dost dlouho\n    }\n    // println!("{}", vysledek);\n}</code></pre><h2>Struct s referencí</h2><p>Pokud struktura obsahuje referenci, musí mít lifetime parametr. Kompilátor tak ověří, že reference nepřežije data, na která odkazuje.</p><pre><code>struct Uzivatel&lt;''a&gt; {\n    jmeno: &amp;''a str,\n}\n\nfn main() {\n    let jmeno = String::from("Karel");\n    let uziv = Uzivatel { jmeno: &amp;jmeno };\n    println!("{}", uziv.jmeno);\n}</code></pre><h2>Elision pravidla</h2><p>Kompilátor dokáže odvodit lifetimes automaticky v jednoduchých případech. Anotaci potřebuješ jen tehdy, kdy pravidla elision nestačí.</p><pre><code>// Elision: kompilátor automaticky přidá ''a\nfn prvni(slova: &amp;[&amp;str]) -> &amp;str {\n    &amp;slova[0]\n}\n\n// Ekvivalentní s explicitní anotací:\nfn prvni_explicit&lt;''a&gt;(slova: &amp;''a [&amp;''a str]) -> &amp;''a str {\n    &amp;slova[0]\n}</code></pre><h2>''static</h2><p><code>''static</code> znamená, že reference žije po celou dobu běhu programu. Všechny stringové literály mají lifetime <code>''static</code>.</p><pre><code>let s: &amp;''static str = "Tento text je ve staticke pameti";</code></pre>', 'lesson', 6, 15, 18),

(@kurs_id, 'Iterátory a closures', '<h2>Iterátor</h2><p>Typ, který implementuje trait <code>Iterator</code> s metodou <code>next()</code>. Vrací <code>Option&lt;Item&gt;</code> — None na konci. Iterátory jsou lazy — nevyhodnocují se, dokud je nezavoláš.</p><pre><code>let v = vec![1, 2, 3, 4, 5];\nlet mut iter = v.iter();\nassert_eq!(iter.next(), Some(&amp;1));\nassert_eq!(iter.next(), Some(&amp;2));\nassert_eq!(iter.next(), Some(&amp;3));\nassert_eq!(iter.next(), None);</code></pre><h2>filter, map, collect</h2><p>Adaptery transformují iterátor. <code>collect</code> materializuje výsledek do kolekce. Typ kolekce určíš typovou anotací nebo <code>Turbofish</code> syntaxí <code>::&lt;Vec&lt;_&gt;&gt;</code>.</p><pre><code>let cisla = vec![1, 2, 3, 4, 5, 6];\n\n// filter + map + collect\nlet suda_ctverce: Vec&lt;i32&gt; = cisla\n    .iter()\n    .filter(|&amp;&amp;x| x % 2 == 0)\n    .map(|&amp;x| x * x)\n    .collect();\nprintln!("{:?}", suda_ctverce);  // [4, 16, 36]\n\n// sum\nlet soucet: i32 = cisla.iter().sum();  // 21\n\n// find\nlet prvni_vetsi = cisla.iter().find(|&amp;&amp;x| x > &amp;3);  // Some(4)</code></pre><h2>Closures</h2><p>Anonymní funkce, které zachycují proměnné z okolního scope. Syntaxe: <code>|parametry| tělo</code>. Typy se většinou odvodí automaticky.</p><pre><code>let nasobek = 3;\nlet nasob = |x: i32| x * nasobek;  // zachycuje nasobek\nprintln!("{}", nasob(5));  // 15\n\n// Uzavření s mutabilním zachycením\nlet mut pocet = 0;\nlet mut pricti = || {\n    pocet += 1;\n    pocet\n};\npricti();\npricti();\nprintln!("{}", pocet);  // 2</code></pre><h2>Ownership v closures</h2><p>Closures zachycují proměnné třemi způsoby, podle kterých implementují traity Fn, FnMut, FnOnce:</p><p>— <code>Fn</code>: pouze čte (neměnná reference)<br/>— <code>FnMut</code>: čte i mění (měnná reference)<br/>— <code>FnOnce</code>: přesune vlastnictví (spotřebuje zachycené hodnoty)</p><pre><code>fn aplikuj&lt;F: Fn(i32) -> i32&gt;(f: F, x: i32) -> i32 {\n    f(x)\n}\n\nlet dvojnasobek = |x| x * 2;\nprintln!("{}", aplikuj(dvojnasobek, 5));  // 10</code></pre>', 'lesson', 7, 15, 18),

(@kurs_id, 'async/await s Tokio', '<h2>async fn</h2><p>Klíčové slovo <code>async</code> před funkcí vytvoří korutinu. Uvnitř používáš <code>await</code> pro čekání na asynchronní operaci. Async funkce vrací <code>Future</code>.</p><pre><code>async fn pozdrav(jmeno: &amp;str) -> String {\n    format!("Ahoj, {}!", jmeno)\n}\n\nasync fn main_logic() {\n    let vysledek = pozdrav("Karel").await;\n    println!("{}", vysledek);\n}</code></pre><h2>Tokio runtime</h2><p>Tokio je nejpopulárnější async runtime. Makro <code>#[tokio::main]</code> automaticky spustí async funkci. V Cargo.toml přidej <code>tokio = { version = "1", features = ["full"] }</code>.</p><pre><code>use tokio::time::{sleep, Duration};\n\n#[tokio::main]\nasync fn main() {\n    println!("Start");\n    sleep(Duration::from_secs(2)).await;\n    println!("Po 2 sekundach");\n}</code></pre><h2>Souběžné úlohy — tokio::spawn</h2><p><code>tokio::spawn</code> spustí asynchronní úlohu na pozadí. Vrací <code>JoinHandle</code> pro čekání na výsledek.</p><pre><code>use tokio::time::{sleep, Duration};\n\n#[tokio::main]\nasync fn main() {\n    let r1 = tokio::spawn(async {\n        sleep(Duration::from_millis(500)).await;\n        "uloha 1"\n    });\n    let r2 = tokio::spawn(async {\n        sleep(Duration::from_millis(300)).await;\n        "uloha 2"\n    });\n    println!("{}", r1.await.unwrap());\n    println!("{}", r2.await.unwrap());\n}</code></pre><h2>join!</h2><p>Makro <code>tokio::join!</code> čeká na více futures souběžně — podobně jako Promise.all. Všechny se spustí paralelně na jednom vlákně.</p><pre><code>async fn stah(url: &amp;str) -> String {\n    // simulace HTTP požadavku\n    sleep(Duration::from_millis(100)).await;\n    format!("data z {}", url)\n}\n\n#[tokio::main]\nasync fn main() {\n    let (a, b) = tokio::join!(\n        stah("https://a.com"),\n        stah("https://b.com"),\n    );\n    println!("{} {}", a, b);\n}</code></pre>', 'lesson', 8, 15, 18),

(@kurs_id, 'Error handling — thiserror + anyhow', '<h2>thiserror</h2><p>Crates <code>thiserror</code> generuje <code>Error</code> trait implementaci pro vlastní chybové typy pomocí derive makra. Eliminuje boilerplate. V Cargo.toml: <code>thiserror = "2"</code>.</p><pre><code>use thiserror::Error;\n\n#[derive(Error, Debug)]\npub enum AppError {\n    #[error("Soubor nenalezen: {0}")]\n    FileNotFound(String),\n    #[error("Neplatny vstup: {field}")]\n    InvalidInput { field: String },\n    #[error("IO chyba")]\n    Io(#[from] std::io::Error),\n}\n\nfn cti() -> Result&lt;String, AppError&gt; {\n    Err(AppError::FileNotFound("data.txt".into()))\n}</code></pre><h2>anyhow</h2><p>Crates <code>anyhow</code> zjednodušuje error handling v aplikacích. Používá jeden typ <code>anyhow::Error</code> pro všechny chyby včetně kontextu. V Cargo.toml: <code>anyhow = "1"</code>.</p><pre><code>use anyhow::{Context, Result};\n\nfn cti_config(cesta: &amp;str) -> Result&lt;String&gt; {\n    std::fs::read_to_string(cesta)\n        .context(format!("Nepodarilo se cist {}", cesta))?\n}\n\nfn main() -> Result&lt;()&gt; {\n    let config = cti_config("config.toml")?;\n    println!("Config: {}", config);\n    Ok(())\n}</code></pre><h2>Kdy co použít</h2><p><strong>Knihovny:</strong> thiserror — definuje konkrétní chybový typ, uživatel knihovny může matchovat varianty.<br/><strong>Aplikace:</strong> anyhow — flexibilní, přidává kontext, nepotřebuješ matchovat varianty.</p><pre><code>// Knihovna: thiserror\npub type LibResult&lt;T&gt; = Result&lt;T, AppError&gt;;\n\n// Aplikace: anyhow\npub type AppResult&lt;T&gt; = anyhow::Result&lt;T&gt;;</code></pre>', 'lesson', 9, 15, 16),

(@kurs_id, 'Testování', '<h2>Unit testy — #[cfg(test)]</h2><p>Testy píšeš do modulu označeného <code>#[cfg(test)]</code>. Každá testovací funkce má atribut <code>#[test]</code>. Spustíš příkazem <code>cargo test</code>.</p><pre><code>pub fn secti(a: i32, b: i32) -> i32 {\n    a + b\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn test_secti() {\n        assert_eq!(secti(2, 3), 5);\n    }\n\n    #[test]\n    fn test_secti_zaporne() {\n        assert_eq!(secti(-1, 1), 0);\n    }\n\n    #[test]\n    #[should_panic]\n    fn test_panic() {\n        panic!("Chyba!");\n    }\n}</code></pre><h2>assert makra</h2><p><code>assert!</code> — ověří bool. <code>assert_eq!</code> a <code>assert_ne!</code> — porovnají hodnoty (vyžadují Debug+PartialEq). Vlastní zpráva: <code>assert!(x, "Selhalo: {}", x)</code>.</p><pre><code>#[test]\nfn test_bool() {\n    let platne = true;\n    assert!(platne);\n    assert_eq!(2 + 2, 4);\n    assert_ne!(2 + 2, 5);\n}</code></pre><h2>Result v testech</h2><p>Test může vracet <code>Result&lt;(), Box&lt;dyn Error&gt;&gt;</code> a používat <code>?</code> operátor místo unwrap.</p><pre><code>use std::fs;\n\n#[test]\nfn test_cteni_souboru() -> Result&lt;(), Box&lt;dyn std::error::Error&gt;&gt; {\n    let obsah = fs::read_to_string("test_data.txt")?;\n    assert!(!obsah.is_empty());\n    Ok(())\n}</code></pre><h2>Integrační testy</h2><p>Umístíš do složky <code>tests/</code> v kořenu projektu. Každý soubor je samostatný crate — testuje veřejné API. Spustí se automaticky s <code>cargo test</code>.</p><pre><code>// tests/integration_test.rs\nuse my_crate::secti;\n\n#[test]\nfn test_integrace() {\n    assert_eq!(secti(10, 20), 30);\n}</code></pre><h2>Ignorované testy</h2><p>Atribut <code>#[ignore]</code> přeskočí test při běhu. Spustíš explicitně: <code>cargo test -- --ignored</code>. Vhodné pro pomalé testy.</p><pre><code>#[test]\n#[ignore]\nfn pomaly_test() {\n    // dlouho trvající operace\n}</code></pre>', 'lesson', 10, 15, 18),

(@kurs_id, 'Actix-web — REST API', '<h2>Základy Actix-web</h2><p>Actix-web je rychlý, pragmatický webový framework. V Cargo.toml: <code>actix-web = "4"</code>. Server spustíš makrem <code>#[actix_web::main]</code>.</p><pre><code>use actix_web::{web, App, HttpServer, HttpResponse, get, post};\n\n#[get("/")]\nasync fn index() -> HttpResponse {\n    HttpResponse::Ok().json(serde_json::json!({"status": "ok"}))\n}\n\n#[actix_web::main]\nasync fn main() -> std::io::Result&lt;()&gt; {\n    HttpServer::new(|| App::new().service(index))\n        .bind("127.0.0.1:8080")?\n        .run()\n        .await\n}</code></pre><h2>Extrakce dat</h2><p>Actix automaticky extrahuje data z požadavku: <code>web::Path</code> (URL parametry), <code>web::Query</code> (query string), <code>web::Json</code> (tělo JSON).</p><pre><code>use serde::Deserialize;\n\n#[derive(Deserialize)]\nstruct UzivatelDto {\n    jmeno: String,\n    vek: u32,\n}\n\n#[post("/users")]\nasync fn vytvor(body: web::Json&lt;UzivatelDto&gt;) -> HttpResponse {\n    HttpResponse::Created().json(serde_json::json!({\n        "jmeno": body.jmeno,\n        "vek": body.vek,\n    }))\n}\n\n#[get("/users/{id}")]\nasync fn detail(path: web::Path&lt;u32&gt;) -> HttpResponse {\n    let id = path.into_inner();\n    HttpResponse::Ok().json(serde_json::json!({"id": id}))\n}</code></pre><h2>Stav aplikace</h2><p>Sdílený stav přes <code>web::Data</code>. Obalí <code>Mutex</code> nebo <code>RwLock</code> pro bezpečný přístup z více handlerů.</p><pre><code>use std::sync::Mutex;\n\nstruct AppState {\n    counter: Mutex&lt;i32&gt;,\n}\n\n#[get("/count")]\nasync fn count(data: web::Data&lt;AppState&gt;) -> HttpResponse {\n    let mut cnt = data.counter.lock().unwrap();\n    *cnt += 1;\n    HttpResponse::Ok().body(format!("Pocet: {}", cnt))\n}\n\n// HttpServer::new(|| {\n//     App::new().app_data(Data::new(AppState { counter: Mutex::new(0) }))\n//              .service(count)\n// })</code></pre>', 'lesson', 11, 15, 20),

(@kurs_id, 'Makra', '<h2>macro_rules!</h2><p>Deklarativní makra — vzorově nahrazují kód při překladu. Syntaxe: <code>macro_rules! jmeno { (vzor) => { expandace } }</code>. Používají <code>$</code> prefix pro metaproměnné.</p><pre><code>macro_rules! say_hello {\n    () => {\n        println!("Ahoj z makra!");\n    };\n    ($jmeno:expr) => {\n        println!("Ahoj, {}!", $jmeno);\n    };\n}\n\nfn main() {\n    say_hello!();          // Ahoj z makra!\n    say_hello!("Karel");   // Ahoj, Karel!\n}</code></pre><h2>Opakující se vzory</h2><p>Specifikátory: <code>$x:expr</code> (výraz), <code>$x:ty</code> (typ), <code>$x:ident</code> (identifikátor), <code>$($x),*</code> (opakování oddělené čárkami).</p><pre><code>macro_rules! vektor {\n    ($($x:expr),*) => {\n        {\n            let mut temp_vec = Vec::new();\n            $(temp_vec.push($x);)*\n            temp_vec\n        }\n    };\n}\n\nfn main() {\n    let v = vektor![1, 2, 3];\n    println!("{:?}", v);  // [1, 2, 3]\n}</code></pre><h2>Procedurální makra</h2><p>Procedurální makra přijímají Token Stream jako vstup a vracejí transformovaný Token Stream. Tři druhy: derive makra, attribute makra, function-like makra. Vyžadují samostatný crate s typem <code>proc-macro = true</code> v Cargo.toml.</p><pre><code>// V crate my_derive (Cargo.toml: proc-macro = true)\nuse proc_macro::TokenStream;\n\n#[proc_macro_derive(HelloMacro)]\npub fn hello_macro_derive(input: TokenStream) -> TokenStream {\n    let ast = syn::parse_macro_input!(input as syn::DeriveInput);\n    let name = &amp;ast.ident;\n    let expanded = quote::quote! {\n        impl #name {\n            pub fn hello_macro() {\n                println!("Ahoj z {}", stringify!(#name));\n            }\n        }\n    };\n    TokenStream::from(expanded)\n}</code></pre><h2>Použití derive makra</h2><pre><code>use my_derive::HelloMacro;\n\n#[derive(HelloMacro)]\nstruct MujTyp;\n\nfn main() {\n    MujTyp::hello_macro();  // "Ahoj z MujTyp"\n}</code></pre>', 'lesson', 12, 15, 20),

(@kurs_id, 'unsafe Rust a FFI', '<h2>Kdy unsafe?</h2><p>Rust garantuje paměťovou bezpečnost kompilátorem. <code>unsafe</code> vypíná některé kontroly — používáš ho pro: surové pointery, volání externích funkcí, mutaci statických proměnných, přístup k unionům, implementaci unsafe traitů.</p><pre><code>unsafe fn nebezpecna_fce(ptr: *const i32) -> i32 {\n    *ptr  // dereference surového pointeru\n}\n\nfn main() {\n    let x = 42;\n    let r = &amp;x as *const i32;\n    unsafe {\n        println!("Hodnota: {}", *r);\n        println!("Pres fci: {}", nebezpecna_fce(r));\n    }\n}</code></pre><h2>unsafe blok vs unsafe funkce</h2><p><code>unsafe fn</code> vyžaduje, aby volající použil unsafe blok. <code>unsafe {}</code> uvnitř bezpečné funkce otevírá nebezpečný blok. Obojí je potřeba — unsafe fn deklaruje kontrakt, unsafe blok potvrzuje, že ho plníš.</p><pre><code>unsafe fn zapis(ptr: *mut i32, val: i32) {\n    *ptr = val;\n}\n\nfn main() {\n    let mut x = 0;\n    let ptr = &amp;mut x as *mut i32;\n    unsafe {\n        zapis(ptr, 99);\n        assert_eq!(*ptr, 99);\n    }\n}\n</code></pre><h2>FFI — volání C</h2><p>Rust může volat funkce z C knihoven přes <code>extern "C"</code>. Typy převádíš přes <code>std::ffi</code> (CString, CStr). Opačným směrem Rust exportuje funkce s <code>#[no_mangle] extern "C"</code>.</p><pre><code>use std::os::raw::c_int;\n\nextern "C" {\n    fn abs(input: c_int) -> c_int;\n}\n\nfn main() {\n    unsafe {\n        let vysledek = abs(-5);\n        println!("abs(-5) = {}", vysledek);  // 5\n    }\n}\n\n// Export Rust funkce pro C\n#[no_mangle]\npub extern "C" fn rust_pozdrav() -> *const u8 {\n    b"Hello from Rust\\0".as_ptr()\n}</code></pre><h2>Bezpečný obal</h2><p>Vždy obal unsafe kód do bezpečného rozhraní. Uživatel TVE knihovny nesmí potřebovat unsafe.</p><pre><code>pub fn bezpecne_cti(v: &amp;Vec&lt;i32&gt;, idx: usize) -> Option&lt;i32&gt; {\n    if idx < v.len() {\n        Some(unsafe { *v.get_unchecked(idx) })\n    } else {\n        None\n    }\n}</code></pre>', 'lesson', 13, 15, 18),

(@kurs_id, 'WebAssembly', '<h2>Rust + WebAssembly</h2><p>Rust se překládá do Wasm — spustíš ho v prohlížeči vedle JavaScriptu. Výhodné pro výpočetně náročné operace: obrázky, kryptografie, simulace. Nástroje: <code>wasm-bindgen</code>, <code>wasm-pack</code>.</p><h2>wasm-bindgen</h2><p>Crates <code>wasm-bindgen</code> propojuje Rust a JavaScript. Atributy <code>#[wasm_bindgen]</code> označují funkce a typy, které budou dostupné z JS.</p><pre><code>use wasm_bindgen::prelude::*;\n\n#[wasm_bindgen]\npub fn secti(a: i32, b: i32) -> i32 {\n    a + b\n}\n\n#[wasm_bindgen]\npub struct Kalkulacka {\n    hodnota: i32,\n}\n\n#[wasm_bindgen]\nimpl Kalkulacka {\n    #[wasm_bindgen(constructor)]\n    pub fn new() -> Self {\n        Kalkulacka { hodnota: 0 }\n    }\n    pub fn pricti(&amp;mut self, x: i32) {\n        self.hodnota += x;\n    }\n    pub fn hodnota(&amp;self) -> i32 {\n        self.hodnota\n    }\n}</code></pre><h2>wasm-pack</h2><p><code>wasm-pack</code> překládá Rust crate do Wasm npm balíčku. Generuje JS glue kód a TypeScript definice.</p><pre><code>cargo install wasm-pack\n\n# V Rust Wasm projektu:\nwasm-pack build --target web\n# Výstup do pkg/ — obsahuje .wasm, .js, .d.ts\n\n# Publikace na npm:\nwasm-pack publish</code></pre><h2>Volání z JavaScriptu</h2><pre><code>// Import vygenerovaný wasm-pack\nimport init, { secti, Kalkulacka } from "./pkg/my_wasm.js";\n\nasync function run() {\n    await init();\n    console.log(secti(3, 4));  // 7\n\n    const k = new Kalkulacka();\n    k.pricti(10);\n    k.pricti(5);\n    console.log(k.hodnota());  // 15\n}\n\nrun();</code></pre><h2>console.log z Rustu</h2><pre><code>#[wasm_bindgen]\nextern "C" {\n    #[wasm_bindgen(js_namespace = console)]\n    fn log(s: &amp;str);\n}\n\n#[wasm_bindgen]\npub fn hello() {\n    log("Ahoj z Wasm!");\n}</code></pre>', 'lesson', 14, 15, 18),

(@kurs_id, 'Serde', '<h2>Serialize a Deserialize</h2><p>Crates <code>serde</code> je standardní framework pro serializaci v Rustu. Derive makra <code>Serialize</code> a <code>Deserialize</code> převádějí struktury do a z formátů. V Cargo.toml: <code>serde = { version = "1", features = ["derive"] }</code>.</p><pre><code>use serde::{Serialize, Deserialize};\n\n#[derive(Serialize, Deserialize, Debug)]\nstruct Uzivatel {\n    jmeno: String,\n    vek: u32,\n    aktivni: bool,\n}\n\nfn main() {\n    let karel = Uzivatel {\n        jmeno: "Karel".into(),\n        vek: 25,\n        aktivni: true,\n    };\n\n    // Serializace do JSON\n    let json = serde_json::to_string(&amp;karel).unwrap();\n    println!("{}", json);\n    // {"jmeno":"Karel","vek":25,"aktivni":true}\n\n    // Deserializace z JSON\n    let parsed: Uzivatel = serde_json::from_str(&amp;json).unwrap();\n    println!("{:?}", parsed);\n}</code></pre><h2>Přejmenování — rename</h2><p><code>#[serde(rename = "name")]</code> přejmenuje pole při serializaci. <code>#[serde(rename_all = "camelCase")]</code> na úrovni struktury převede vše na camelCase.</p><pre><code>#[derive(Serialize, Deserialize)]\n#[serde(rename_all = "camelCase")]\nstruct UzivatelDto {\n    jmeno: String,        // serializuje se jako "jmeno"\n    vek: u32,             // "vek"\n    je_admin: bool,       // "jeAdmin" (camelCase)\n}\n\n// Jednotlivé pole\n#[derive(Serialize, Deserialize)]\nstruct Config {\n    #[serde(rename = "apiKey")]\n    api_klic: String,\n}</code></pre><h2>Výchozí hodnoty</h2><p><code>#[serde(default)]</code> vyplní výchozí hodnoty chybějících polí. Vlastní výchozí hodnota přes funkci.</p><pre><code>#[derive(Serialize, Deserialize, Debug)]\nstruct Nastaveni {\n    #[serde(default)]\n    jazyk: String,  // výchozí ""\n    #[serde(default = "vychozi_limit")]\n    limit: u32,\n}\n\nfn vychozi_limit() -> u32 { 100 }\n\nfn main() {\n    let json = r#"{}"#;\n    let n: Nastaveni = serde_json::from_str(json).unwrap();\n    println!("{:?}", n);  // Nastaveni { jazyk: "", limit: 100 }\n}</code></pre><h2>Skip a flatten</h2><p><code>#[serde(skip)]</code> vynechá pole. <code>#[serde(flatten)]</code> vloží pole nadřazené struktury přímo.</p><pre><code>#[derive(Serialize, Deserialize)]\nstruct Metadata {\n    verze: String,\n}\n\n#[derive(Serialize, Deserialize)]\nstruct Dokument {\n    nazev: String,\n    #[serde(flatten)]\n    meta: Metadata,\n}</code></pre>', 'lesson', 15, 15, 18),

(@kurs_id, 'SQLx — async databáze', '<h2>SQLx</h2><p>Crates <code>sqlx</code> je asynchronní databázový pool s compile-time ověřováním SQL dotazů. Podporuje PostgreSQL, MySQL/MariaDB, SQLite. V Cargo.toml: <code>sqlx = { version = "0.8", features = ["runtime-tokio", "sqlite"] }</code>.</p><h2>Compile-time ověření</h2><p>Makro <code>sqlx::query!</code> ověří SQL dotaz při překladu proti skutečné databázi (nebo uloženému schématu). Chybný dotaz neprojde kompilací.</p><pre><code>use sqlx::sqlite::SqlitePool;\n\n#[derive(Debug, sqlx::FromRow)]\nstruct Uzivatel {\n    id: i64,\n    jmeno: String,\n    vek: i32,\n}\n\nasync fn seznam(pool: &amp;SqlitePool) -> Result&lt;Vec&lt;Uzivatel&gt;, sqlx::Error&gt; {\n    // Compile-time ověřeno:\n    sqlx::query_as!(\n        Uzivatel,\n        "SELECT id, jmeno, vek FROM uzivatele WHERE vek > $1",\n        18\n    )\n    .fetch_all(pool)\n    .await\n}</code></pre><h2>Pool a migrace</h2><p>Pool sdílí připojení. Migrace se spouští makrem <code>sqlx::migrate!</code> z adresáře <code>migrations/</code>.</p><pre><code>use sqlx::sqlite::SqlitePoolOptions;\n\n#[tokio::main]\nasync fn main() -> Result&lt;(), Box&lt;dyn std::error::Error&gt;&gt; {\n    let pool = SqlitePoolOptions::new()\n        .max_connections(5)\n        .connect("sqlite://app.db").await?;\n\n    // Spustí migrace z adresare migrations/\n    sqlx::migrate!("./migrations").run(&amp;pool).await?;\n\n    // Vlozeni\n    sqlx::query("INSERT INTO uzivatele (jmeno, vek) VALUES ($1, $2)")\n        .bind("Karel")\n        .bind(25)\n        .execute(&amp;pool)\n        .await?;\n\n    Ok(())\n}</code></pre><h2>Offline mód</h2><p>Pokud nemáš databázi při překladu k dispozici, použij <code>SQLX_OFFLINE=true</code>. Uložená metadata dotazů z <code>cargo sqlx prepare</code> se použijí místo přímého připojení.</p><pre><code># Ulož dotaz metadata\ncargo sqlx prepare\n\n# Kompilace bez databáze\nSQLX_OFFLINE=true cargo build</code></pre>', 'lesson', 16, 15, 18),

(@kurs_id, 'Tauri 2.0 — desktopové aplikace', '<h2>Co je Tauri?</h2><p>Tauri 2.0 je framework pro tvorbu desktopových (a mobilních) aplikací s frontendem ve web technologiích (HTML/CSS/JS) a backendem v Rustu. Oproti Electronu je binárka mnohem menší a paměťová stopa nižší, protože Tauri používá systémový WebView místo zabudovaného Chromium.</p><h2>Architektura VeVit Files</h2><p>Projekt VeVit Files je souborový manažer postavený na Tauri 2.0. Frontend (Svelte) komunikuje s Rust backendem přes Tauri commands. Rust zpracovává souborové operace, zatímco frontend zobrazuje uživatelské rozhraní.</p><pre><code>// Struktura projektu VeVit Files\nvevit-files/\n  src-tauri/\n    src/\n      main.rs       // vstupní bod\n      lib.rs         // registrace příkazů a pluginů\n      commands/\n        files.rs     // souborové operace\n        system.rs    // systémové informace\n    Cargo.toml\n    tauri.conf.json\n  src/              // Svelte frontend\n    App.svelte\n    lib/\n      api.ts        // Tauri invoke wrapper</code></pre><h2>Tauri commands — Rust backend</h2><p>Funkce označené <code>#[tauri::command]</code> jsou dostupné z frontendu přes <code>invoke</code>. Parametry se automaticky deserializují z JSONu, návratové hodnoty serializují do JSONu.</p><pre><code>// src-tauri/src/commands/files.rs\nuse serde::Serialize;\nuse std::path::PathBuf;\n\n#[derive(Serialize)]\npub struct FileInfo {\n    pub name: String,\n    pub path: String,\n    pub is_dir: bool,\n    pub size: u64,\n    pub modified: String,\n}\n\n#[tauri::command]\npub fn list_directory(path: String) -> Result&lt;Vec&lt;FileInfo&gt;, String&gt; {\n    let dir = PathBuf::from(&amp;path);\n    if !dir.is_dir() {\n        return Err(format!("Cesta neni adresar: {}", path));\n    }\n    let mut files = Vec::new();\n    for entry in std::fs::read_dir(&amp;dir).map_err(|e| e.to_string())? {\n        let entry = entry.map_err(|e| e.to_string())?;\n        let meta = entry.metadata().map_err(|e| e.to_string())?;\n        let name = entry.file_name().to_string_lossy().to_string();\n        let modified = meta.modified()\n            .map_err(|e| e.to_string())?\n            .duration_since(std::time::UNIX_EPOCH)\n            .map_err(|e| e.to_string())?\n            .as_secs()\n            .to_string();\n        files.push(FileInfo {\n            name,\n            path: entry.path().to_string_lossy().to_string(),\n            is_dir: meta.is_dir(),\n            size: meta.len(),\n            modified,\n        });\n    }\n    Ok(files)\n}\n\n#[tauri::command]\npub fn create_file(path: String, content: String) -> Result&lt;(), String&gt; {\n    std::fs::write(&amp;path, &amp;content).map_err(|e| e.to_string())\n}\n\n#[tauri::command]\npub fn delete_file(path: String) -> Result&lt;(), String&gt; {\n    let p = PathBuf::from(&amp;path);\n    if p.is_dir() {\n        std::fs::remove_dir_all(&amp;p).map_err(|e| e.to_string())\n    } else {\n        std::fs::remove_file(&amp;p).map_err(|e| e.to_string())\n    }\n}\n\n#[tauri::command]\npub fn rename_file(from: String, to: String) -> Result&lt;(), String&gt; {\n    std::fs::rename(&amp;from, &amp;to).map_err(|e| e.to_string())\n}\n\n#[tauri::command]\npub fn get_file_info(path: String) -> Result&lt;FileInfo, String&gt; {\n    let meta = std::fs::metadata(&amp;path).map_err(|e| e.to_string())?;\n    let p = PathBuf::from(&amp;path);\n    Ok(FileInfo {\n        name: p.file_name().unwrap().to_string_lossy().to_string(),\n        path: path.clone(),\n        is_dir: meta.is_dir(),\n        size: meta.len(),\n        modified: meta.modified()\n            .map_err(|e| e.to_string())?\n            .duration_since(std::time::UNIX_EPOCH)\n            .map_err(|e| e.to_string())?\n            .as_secs()\n            .to_string(),\n    })\n}</code></pre><h2>Registrace commands v lib.rs</h2><pre><code>// src-tauri/src/lib.rs\nuse tauri::Manager;\n\nmod commands;\n\n#[cfg_attr(mobile, tauri::mobile_entry_point)]\npub fn run() {\n    tauri::Builder::default()\n        .plugin(tauri_plugin_opener::init())\n        .plugin(tauri_plugin_dialog::init())\n        .plugin(tauri_plugin_fs::init())\n        .invoke_handler(tauri::generate_handler![\n            commands::files::list_directory,\n            commands::files::create_file,\n            commands::files::delete_file,\n            commands::files::rename_file,\n            commands::files::get_file_info,\n        ])\n        .run(tauri::generate_context!())\n        .expect("Chyba pri spusteni Tauri");\n}</code></pre><h2>Volání z JavaScriptu — invoke</h2><p>Frontend volá Rust příkazy přes <code>window.__TAURI__.core.invoke()</code> (Tauri 2.0). Doporučujeme vytvořit typově bezpečný wrapper.</p><pre><code>// src/lib/api.ts — VeVit Files API wrapper\nimport { invoke } from "@tauri-apps/api/core";\n\ninterface FileInfo {\n  name: string;\n  path: string;\n  is_dir: boolean;\n  size: number;\n  modified: string;\n}\n\nexport async function listDirectory(path: string): Promise&lt;FileInfo[]&gt; {\n  return invoke&lt;FileInfo[]&gt;("list_directory", { path });\n}\n\nexport async function createFile(path: string, content: string): Promise&lt;void&gt; {\n  return invoke("create_file", { path, content });\n}\n\nexport async function deleteFile(path: string): Promise&lt;void&gt; {\n  return invoke("delete_file", { path });\n}\n\nexport async function renameFile(from: string, to: string): Promise&lt;void&gt; {\n  return invoke("rename_file", { from, to });\n}\n\nexport async function getFileInfo(path: string): Promise&lt;FileInfo&gt; {\n  return invoke&lt;FileInfo&gt;("get_file_info", { path });\n}</code></pre><h2>Souborový systém — Tauri plugin</h2><p>Tauri 2.0 nabízí plugin <code>tauri-plugin-fs</code> pro práci se souborovým systémem přímo z frontendu. Vyžaduje oprávnění v <code>capabilities</code> konfiguraci.</p><pre><code>// Čtení souboru přes plugin z JavaScriptu\nimport { readTextFile, writeTextFile, exists } from "@tauri-apps/plugin-fs";\n\nasync function nactiAuloz(cesta: string) {\n  if (await exists(cesta)) {\n    const obsah = await readTextFile(cesta);\n    console.log("Obsah:", obsah);\n    await writeTextFile(cesta, obsah + "\\nUpraveno");\n  } else {\n    await writeTextFile(cesta, "Novy soubor");\n  }\n}</code></pre><h2>Oprávnění — capabilities</h2><p>V Tauri 2.0 se oprávnění konfigurují v <code>src-tauri/capabilities/default.json</code>. Omezíš, které příkazy a pluginy jsou dostupné.</p><pre><code>{\n  "identifier": "default",\n  "description": "Default capabilities for VeVit Files",\n  "windows": ["main"],\n  "permissions": [\n    "core:default",\n    "opener:default",\n    "dialog:default",\n    "fs:default",\n    "fs:allow-read-text-file",\n    "fs:allow-write-text-file",\n    "fs:allow-exists"\n  ]\n}</code></pre><h2>Systémový dialog</h2><p>Plugin <code>tauri-plugin-dialog</code> otevírá nativní dialogy — otevřít, uložit, potvrdit.</p><pre><code>import { open, save } from "@tauri-apps/plugin-dialog";\n\n// Dialog pro výběr souboru/adresáře\nconst vybrano = await open({\n  multiple: false,\n  directory: false,\n  title: "Vyber soubor",\n});\nif (vybrano) {\n  console.log("Vybrano:", vybrano);\n}\n\n// Dialog pro uložení\nconst cestaUlozeni = await save({\n  filters: [{ name: "Text", extensions: ["txt", "md"] }],\n});</code></pre>', 'lesson', 17, 15, 25),

(@kurs_id, 'Benchmarking — Criterion', '<h2>Proč benchmark?</h2><p>Micro-benchmarking měří výkon jednotlivých funkcí. Rust nabízí vestavěné <code>#[bench]</code> (noční), ale stabilní ekosystém používá crates <code>criterion</code>. V Cargo.toml: <code>criterion = { version = "0.5", features = ["html_reports"] }</code>.</p><h2>Základní benchmark</h2><pre><code>use criterion::{black_box, criterion_group, criterion_main, Criterion};\n\nfn benchmark_secti(c: &amp;mut Criterion) {\n    c.bench_function("secti_1000", |bencher| {\n        bencher.iter(|| {\n            let mut sum = 0;\n            for i in 0..1000 {\n                sum += black_box(i);\n            }\n            sum\n        })\n    });\n}\n\nfn benchmark_fibonacci(c: &amp;mut Criterion) {\n    fn fib(n: u64) -> u64 {\n        if n <= 1 { return n; }\n        fib(n - 1) + fib(n - 2)\n    }\n    c.bench_function("fibonacci_20", |bencher| {\n        bencher.iter(|| fib(black_box(20)))\n    });\n}\n\ncriterion_group!(benches, benchmark_secti, benchmark_fibonacci);\ncriterion_main!(benches);</code></pre><h2>black_box</h2><p><code>black_box</code> zabrání kompilátoru optimalizovat výpočet — simuluje reálné použití, kdy je výsledek skutečně použit.</p><h2>Porovnání funkcí — BenchWithInputs</h2><pre><code>use criterion::BatchSize;\n\nfn benchmark_search(c: &amp;mut Criterion) {\n    let data: Vec&lt;i32&gt; = (0..10_000).collect();\n    c.bench_function("binary_search", |bencher| {\n        bencher.iter_batched(\n            || 5000,  // vstup\n            |target| data.binary_search(&amp;target),\n            BatchSize::SmallInput,\n        )\n    });\n}</code></pre><h2>Porovnání s předchozím během</h2><p>Criterion automaticky porovná výsledky s předešlým během a upozorní na regresi. Výstup v <code>target/criterion/</code> obsahuje HTML reporty s grafy.</p><pre><code>cargo bench\n# Výstup: target/criterion/report/index.html\n# Porovnání: target/criterion/&lt;funkce&gt;/report/index.html</code></pre><h2>Parametrizované benchmarky</h2><pre><code>use criterion::ParameterizedBenchmark;\n\nfn benchmark_param(c: &amp;mut Criterion) {\n    let sizes = vec![100, 1_000, 10_000];\n    for size in sizes {\n        c.bench_function(&amp;format!("sort_{}", size), |bencher| {\n            bencher.iter(|| {\n                let mut v: Vec&lt;i32&gt; = (0..size).rev().collect();\n                v.sort();\n                black_box(v)\n            })\n        });\n    }\n}</code></pre>', 'lesson', 18, 15, 16),

(@kurs_id, 'CLI nástroj', '<h2>clap — argumenty příkazové řádky</h2><p>Crates <code>clap</code> s feature <code>derive</code> deklaruje CLI rozhraní pomocí struktur. V Cargo.toml: <code>clap = { version = "4", features = ["derive"] }</code>.</p><pre><code>use clap::Parser;\n\n/// VeVit souborovy nastroj\n#[derive(Parser, Debug)]\n#[command(name = "vevit-cli")]\n#[command(version, about = "Sprava souboru z prikazove radky")]\nstruct Cli {\n    /// Cesta k adresari\n    #[arg(default_value = ".")]\n    cesta: String,\n\n    /// Zobraz skryte soubory\n    #[arg(short = ''a'', long)]\n    vse: bool,\n\n    /// Serad podle velikosti\n    #[arg(short = ''s'', long)]\n    velikost: bool,\n\n    /// Pocet zobrazenych souboru\n    #[arg(short = ''n'', long, default_value_t = 20)]\n    limit: usize,\n}</code></pre><h2>Kompletní příklad — souborový manažer CLI</h2><pre><code>use clap::{Parser, Subcommand};\nuse anyhow::Result;\nuse std::path::PathBuf;\n\n#[derive(Parser)]\n#[command(name = "vevit-cli", about = "VeVit souborovy nastroj")]\nstruct Cli {\n    #[command(subcommand)]\n    prikaz: Prikaz,\n}\n\n#[derive(Subcommand)]\nenum Prikaz {\n    /// Vypis obsah adresare\n    List {\n        #[arg(default_value = ".")]\n        cesta: String,\n        /// Rekurzivne\n        #[arg(short = ''r'', long)]\n        recursive: bool,\n    },\n    /// Vytvor soubor\n    Create {\n        cesta: String,\n        #[arg(short = ''c'', long)]\n        content: Option&lt;String&gt;,\n    },\n    /// Smaz soubor nebo adresar\n    Remove {\n        cesta: String,\n        /// Smaz i neprazdny adresar\n        #[arg(short = ''f'', long)]\n        force: bool,\n    },\n    /// Informace o souboru\n    Info {\n        cesta: String,\n    },\n}\n\nfn main() -> Result&lt;()&gt; {\n    let cli = Cli::parse();\n    match cli.prikaz {\n        Prikaz::List { cesta, recursive } => {\n            let path = PathBuf::from(&amp;cesta);\n            if recursive {\n                for entry in walkdir::WalkDir::new(&amp;path) {\n                    println!("{}", entry?.path().display());\n                }\n            } else {\n                for entry in std::fs::read_dir(&amp;path)? {\n                    println!("{}", entry?.path().display());\n                }\n            }\n        }\n        Prikaz::Create { cesta, content } => {\n            let data = content.unwrap_or_default();\n            std::fs::write(&amp;cesta, &amp;data)?;\n            println!("Vytvoren: {}", cesta);\n        }\n        Prikaz::Remove { cesta, force } => {\n            let p = PathBuf::from(&amp;cesta);\n            if p.is_dir() &amp;&amp; force {\n                std::fs::remove_dir_all(&amp;p)?;\n            } else if p.is_dir() {\n                std::fs::remove_dir(&amp;p)?;\n            } else {\n                std::fs::remove_file(&amp;p)?;\n            }\n            println!("Smazano: {}", cesta);\n        }\n        Prikaz::Info { cesta } => {\n            let meta = std::fs::metadata(&amp;cesta)?;\n            println!("Cesta:  {}", cesta);\n            println!("Adresar: {}", meta.is_dir());\n            println!("Velikost: {} B", meta.len());\n            println!("Jen cteni: {}", meta.permissions().readonly());\n        }\n    }\n    Ok(())\n}</code></pre><h2>Spuštění</h2><pre><code>cargo run -- list ./src\n# Vypise obsah adresare ./src\n\ncargo run -- create readme.txt -c "Ahoj VeVit"\n# Vytvori soubor readme.txt s obsahem\n\ncargo run -- info Cargo.toml\n# Cesta:  Cargo.toml\n# Adresar: false\n# Velikost: 289 B\n# Jen cteni: false\n\ncargo run -- --help\n# Zobrazi napovedu vygenerovanou clapem</code></pre>', 'lesson', 19, 15, 22),

(@kurs_id, 'Shrnutí — ekosystém Rustu', '<h2>Co se naučil(a)</h2><p>Prošel(a) jsi základy Rustu od ownershipu přes async/await až po Tauri desktopové aplikace. Rust tě naučil myslet na paměť a bezpečnost už při překladu — borrow checker je tvůj spojenec, ne nepřítel.</p><h2>Klíčové krabice ekosystému</h2><pre><code>// Web\nactix-web     // HTTP framework\naxum          // Ergonomický framework od Tokio\nreqwest       // HTTP klient\n\n// Async\n(tokio)       // Async runtime\n(async-std)   // Alternativní runtime\n\n// Serializace\nserde + serde_json  // JSON a další formáty\n\n// Databáze\nsqlx          // Compile-time ověřené SQL\ndiesel        // ORM\nsea-orm       // Async ORM\n\n// Desktop\n(tauri)       // Rust + Web frontend\n\n// CLI\n(clap)        // Argumenty příkazové řádky\nanyhow        // Zjednodušený error handling\n\n// Testování\ncriterion    // Benchmarking\nproptest      // Property-based testing\n\n// Wasm\n(wasm-bindgen)  // Rust ↔ JavaScript\n(wasm-pack)     // Balení pro npm</code></pre><h2>Kde Rust vyniká</h2><p><strong>Systémové programování:</strong> operační systémy, drivery, embedded — bezpečnost paměti bez GC.</p><p><strong>CLI nástroje:</strong> rychlé spuštění, jednoduchá distribuce jako jedna binárka.</p><p><strong>Web služby:</strong> vysoká propustnost, nízká latence, bezpečnost.</p><p><strong>Desktopové aplikace:</strong> Tauri — malá binárka, Rust backend, webový frontend.</p><p><strong>WebAssembly:</strong> Rust je nejlepší jazyk pro Wasm — kompaktní výstup, žádný runtime.</p><p><strong>Kryptografie a blockchain:</strong> Solana, Parity, Zcash.</p><p><strong>Herní vývoj:</strong> Bevy engine, macroquad.</p><h2>Zdroje</h2><pre><code>// Oficiální\nhttps://doc.rust-lang.org/book/     // The Rust Programming Language\nhttps://doc.rust-lang.org/std/       // Std library docs\nhttps://rust-by-example.extremelycoolandnice.net/\n\n// Komunita\nhttps://this-week-in-rust.org/       // Týdenní zprávy\nhttps://users.rust-lang.org/        // Fórum\nhttps://crates.io                    // Registr krabic\n\n// Cvičení\nhttps://exercism.org/tracks/rust     // Exercism Rust track\nhttps://github.com/rust-lang/rustlings  // Rustlings</code></pre><h2>Další kroky</h2><p>Připoj se k Rust komunitě, čti This Week in Rust, přispěj na crates.io. Vyber si oblast (web, systém, Wasm, Tauri) a postav reálný projekt. Rust se nejlépe učí praxí — tak jdi a programuj!</p>', 'lesson', 20, 15, 15);


