SET @qfin = LAST_INSERT_ID();

INSERT INTO quizzes (lesson_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
(@qfin, 'Kdo je vlastníkem (owner) hodnoty v Rustu?', 'Každá proměnná odkazující na ni', 'Právě jedna proměnná', 'Systém garbage collectoru', 'Všechny reference', 'b', 'Rust má pravidlo: v jednu chvíli existuje právě jeden owner hodnoty.', 1),
(@qfin, 'Co dělá operátor ? na Result<T,E>?', 'Vypíše chybu', 'Pokud Err, předčasně vrátí chybu z funkce; pokud Ok, rozbalí hodnotu', 'Ignoruje chybu', 'Zabije proces', 'b', 'Operátor ? zkracuje error handling — Err se šíří, Ok se rozbalí.', 2),
(@qfin, 'Jaký je rozdíl mezi &T a &mut T?', 'Žádný', '&T je neměnná reference, &mut T je měnná reference', '&T je heap, &mut T je stack', '&T je static, &mut T je dynamic', 'b', '&T dovoluje jen čtení, &mut T dovoluje čtení i zápis — ale v daném scope může existovat jen jedna &mut reference.', 3),
(@qfin, 'Co je borrow checker?', 'Runtime debugger', 'Část kompilátoru ověřující pravidla referencí', 'Testovací framework', 'Formátovač kódu', 'b', 'Borrow checker staticky ověřuje pravidla ownershipu a referencí při překladu.', 4),
(@qfin, 'K čemu slouží #[derive(Debug)]?', 'Přidá debug symboly', 'Automaticky implementuje trait Debug pro pretty-print ({:?})', 'Zapne ladění', 'Vytvoří log soubor', 'b', 'Derive Debug generuje implementaci traitu Debug — umožní println!("{:?}", x).', 5),
(@qfin, 'Co vrací Option<T> pokud hodnota chybí?', 'null', 'None', 'Err', '0', 'b', 'Rust nemá null — nepřítomnost hodnoty se vyjadřuje variantou None typu Option<T>.', 6),
(@qfin, 'Jaký trait implementuje async funkce pod kapotou?', 'Future', 'Iterator', 'Stream', 'Thread', 'a', 'Async funkce vrací typ implementující trait Future, který je vyhodnocen runtime (např. Tokio).', 7),
(@qfin, 'Co je #[tauri::command] v Tauri 2.0?', 'Dekorátor frontendu', 'Označí Rust funkci jako dostupnou z JS přes invoke', 'Spustí HTTP server', 'Zaregistruje plugin', 'b', 'Atribut #[tauri::command] zpřístupní Rust funkci frontendu přes window.__TAURI__.core.invoke().', 8),
(@qfin, 'Co dělá serde rename_all = "camelCase"?', 'Přejmenuje crate', 'Převede všechna pole structu na camelCase při serializaci', 'Změní název structu', 'Převede JSON na YAML', 'b', 'Atribut #[serde(rename_all = "camelCase")] automaticky převede snake_case pole na camelCase v JSON výstupu.', 9),
(@qfin, 'Co znamená ''static v Rustu?', 'Hodnota je na stacku', 'Reference žije po celou dobu běhu programu', 'Hodnota je konstantní', 'Hodnota je v thread-local paměti', 'b', 'Lifetime ''static zaručuje, že reference je platná po celou dobu běhu programu. Všechny stringové literály mají ''static lifetime.', 10);


